const AuthContext = createContext(null);
const ToastContext = createContext(null);

function useAuth() { return useContext(AuthContext); }
function useToast() { return useContext(ToastContext); }

function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);
  const push = (message, type = 'success') => {
    const id = Date.now() + Math.random();
    setToasts((current) => [...current, { id, message, type }]);
    setTimeout(() => setToasts((current) => current.filter((toast) => toast.id !== id)), 3800);
  };
  return <ToastContext.Provider value={{ push }}>
    {children}
    <div className="toast-stack" aria-live="polite">{toasts.map((toast) => <div key={toast.id} className={`toast toast-${toast.type}`}><span>{toast.type === 'success' ? <Check size={16} /> : <X size={16} />}</span>{toast.message}</div>)}</div>
  </ToastContext.Provider>;
}

function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => { api.me().then((data) => setUser(data.user)).catch(() => {}).finally(() => setLoading(false)); }, []);
  const login = async (body) => { const data = await api.login(body); localStorage.setItem('sponsor_match_token', data.token); setUser(data.user); return data.user; };
  const register = async (body) => { const data = await api.register(body); localStorage.setItem('sponsor_match_token', data.token); setUser(data.user); return data.user; };
  const logout = () => { localStorage.removeItem('sponsor_match_token'); setUser(null); };
  return <AuthContext.Provider value={{ user, loading, login, register, logout }}>{children}</AuthContext.Provider>;
}

function App() {
  return <AuthProvider><ToastProvider><RoutesRoot /></ToastProvider></AuthProvider>;
}

export default App;

function RoutesRoot() {
  const { user, loading } = useAuth();
  if (loading) return <div className="page-loader"><div className="loader-mark">SM</div><span>Opening the matchroom…</span></div>;
  return <RoutesRootInner user={user} />;
}

function RoutesRootInner({ user }) {
  return <Routes>
    <Route path="/" element={<EditorialLandingPage />} />
    <Route path="/auth" element={user ? <Navigate to={user.role === 'BRAND' ? '/brand/dashboard' : '/creator/dashboard'} replace /> : <AuthPage />} />
    <Route path="/brand/*" element={<ProtectedRoute role="BRAND"> <BrandApp /> </ProtectedRoute>} />
    <Route path="/creator/*" element={<ProtectedRoute role="CREATOR"> <CreatorApp /> </ProtectedRoute>} />
    <Route path="*" element={<Navigate to="/" replace />} />
  </Routes>;
}

