  const fallback = { _id: 'coffee-house', name: 'Coimbatore Coffee House', category: 'Food & beverage', location: 'Coimbatore', description: 'Independent coffee, good light and a table for your next idea.', address: '12, Race Course Road, Coimbatore', contactEmail: 'demo@coffeeco.in', phone: '+91 422 245 0188', socials: { instagram: 'https://instagram.com/coimbatorecoffeehouse', facebook: 'https://facebook.com/coimbatorecoffeehouse' }, emailVerified: true, phoneVerified: true };
