function CreatorProfileLive() {
  const { data, setData } = useRemote('/api/creators/profile', { creator: DEMO_CREATORS[0] }); const { user } = useAuth(); const [editing, setEditing] = useState(false); const creator = data?.creator || DEMO_CREATORS[0];
  return <div className="dashboard-page"><PageHeader kicker="Public creator profile" title="Your proof, in one place." description="This is the version of your work brands see first."><button className="button button-outline" onClick={() => setEditing(true)}><PenLine size={16} /> Edit profile</button></PageHeader><div className="public-profile-card"><div className="public-profile-main"><ImageOrInitial src={creator.image} alt={creator.name} className="profile-photo" /><div><Badge tone="mint" icon={<BadgeCheck size={13} />}>Verified creator</Badge><h2>{creator.name}</h2><p>{creator.username} · {creator.category} · {creator.location}</p><span>{creator.bio}</span><SocialLinks socials={creator.socials} /></div></div><div className="profile-proof-hero"><span className="page-kicker">Impact first</span><strong>{creator.receipts?.filter((receipt) => receipt.status === 'BRAND_VERIFIED').length || creator.verifiedReceipts || 0}</strong><span>verified receipts</span><Badge tone="mint"><BadgeCheck size={13} /> Brand verified</Badge></div></div><div className="profile-section-heading"><div><div className="section-kicker coral-kicker">Impact</div><h2>Receipts</h2></div><span>Proof of work, reviewed by the people who saw it.</span></div><div className="public-receipt-grid">{(creator.receipts || []).map((receipt, index) => <ReceiptCard key={receipt._id || index} receipt={receipt} />)}</div><div className="profile-detail-grid creator-profile-lower"><section className="panel profile-vouches"><PanelTitle title="Verified contact" action={<Badge tone="mint"><BadgeCheck size={13} /> Trust layer</Badge>} /><ContactTrust profile={creator} /><p className="panel-intro">Email and mobile details are kept private, but their verification status helps brands know this profile is real.</p></section><section className="panel profile-vouches"><PanelTitle title="Verified vouches" action={<Badge tone="yellow">{creator.vouches || 0} total</Badge>} /><VouchCard creator={creator} /><VouchCard creator={creator} second /></section><section className="panel portfolio-panel"><PanelTitle title="Previous work" action={<span className="quiet-label">View portfolio</span>} /><div className="portfolio-grid"><img src={PHOTO.cafe} alt="Food campaign" /><img src={PHOTO.product} alt="Product story" /><img src={PHOTO.studio} alt="Studio campaign" /></div></section></div>{editing && <ProfileEditor role="CREATOR" profile={{ ...creator, contactEmail: creator.contactEmail || creator.email || user?.email }} onClose={() => setEditing(false)} onSaved={(next) => setData({ creator: next })} />}</div>;
}

function CreatorDiscovery() {
  const { data, loading } = useRemote('/api/creators', { creators: DEMO_CREATORS }); const { push } = useToast();
  const [query, setQuery] = useState(''); const [impact, setImpact] = useState(''); const [category, setCategory] = useState(''); const [location, setLocation] = useState(''); const [platform, setPlatform] = useState(''); const [verifiedOnly, setVerifiedOnly] = useState(false); const [sortProof, setSortProof] = useState(true); const [showFilters, setShowFilters] = useState(false);
  const creators = data?.creators ?? DEMO_CREATORS; const categories = [...new Set(creators.map((creator) => creator.category).filter(Boolean))]; const locations = [...new Set(creators.map((creator) => creator.location).filter(Boolean))]; const visible = creators.filter((creator) => { const q = query.toLowerCase().trim(); const receipts = creator.receipts || []; const text = `${creator.name} ${creator.category} ${creator.location} ${creator.audience} ${creator.bio}`.toLowerCase(); const impactMatch = !impact || receipts.some((receipt) => `${receipt.type} ${receipt.result} ${receipt.description}`.toLowerCase().includes(impact.toLowerCase())); const platformMatch = !platform || creator.platforms?.some((item) => item.toLowerCase().includes(platform.toLowerCase())); return (!q || text.includes(q)) && impactMatch && (!category || creator.category === category) && (!location || creator.location === location) && platformMatch && (!verifiedOnly || (creator.verifiedReceipts || 0) > 0); }).sort((a, b) => sortProof ? (b.verifiedReceipts || 0) - (a.verifiedReceipts || 0) : 0);
  return <div className="dashboard-page"><PageHeader kicker="Creator discovery" title="Find the proof behind the profile." description="Followers are context. Search for the impact that fits your brief."><button className={`button ${sortProof ? 'button-dark' : 'button-outline'}`} onClick={() => setSortProof(!sortProof)}><Receipt size={16} /> {sortProof ? 'Impact first' : 'Sort by fit'}</button></PageHeader><div className="impact-callout"><div className="impact-callout-icon"><Receipt size={22} /></div><div><strong>Search by impact</strong><span>Find creators by what they have achieved, not just the audience they have collected.</span></div><Badge tone="coral">Receipts, not reach</Badge></div><div className="filter-bar"><div className="search-field"><Search size={17} /><input placeholder="Search creator, category or city" value={query} onChange={(event) => setQuery(event.target.value)} /></div><div className="select-wrap"><Filter size={15} /><select value={impact} onChange={(event) => setImpact(event.target.value)}><option value="">All impact types</option><option value="Footfall">Proven footfall</option><option value="Coupon">Coupon conversions</option><option value="Customer">Customer responses</option><option value="Purchase">Purchase / conversion</option><option value="Campaign">Campaign results</option><option value="Vouch">Business vouches</option></select></div><button className={`filter-more ${showFilters ? 'active' : ''}`} onClick={() => setShowFilters(!showFilters)}><Settings size={16} /> {showFilters ? 'Hide filters' : 'More filters'}</button></div>{showFilters && <div className="filter-bar filter-bar-secondary"><div className="select-wrap"><span>Category</span><select value={category} onChange={(event) => setCategory(event.target.value)}><option value="">All categories</option>{categories.map((item) => <option key={item}>{item}</option>)}</select></div><div className="select-wrap"><span>Location</span><select value={location} onChange={(event) => setLocation(event.target.value)}><option value="">All locations</option>{locations.map((item) => <option key={item}>{item}</option>)}</select></div><div className="select-wrap"><span>Platform</span><select value={platform} onChange={(event) => setPlatform(event.target.value)}><option value="">Any platform</option><option>Instagram</option><option>YouTube</option><option>TikTok</option><option>Twitch</option></select></div><label className="filter-check"><input type="checkbox" checked={verifiedOnly} onChange={(event) => setVerifiedOnly(event.target.checked)} /> Only brand-verified proof</label><button className="quiet-button" onClick={() => { setCategory(''); setLocation(''); setPlatform(''); setVerifiedOnly(false); setImpact(''); setQuery(''); }}>Clear all</button></div>}{loading && <div className="inline-loading">Loading creators...</div>}<div className="discovery-context"><span><strong>{visible.length}</strong> creators in your matchroom</span><span><span className="proof-legend" /> verified proof <span className="vouch-legend" /> trusted delivery</span></div><div className="creator-grid">{visible.map((creator) => <CreatorCard key={creator._id} creator={creator} />)}</div>{!visible.length && <EmptyState icon={<Search />} title="No creators found" text="Try clearing one of the filters or searching a broader category." />}</div>;
}

function MessagesPageLive({ role }) {
  const fallback = [{ _id: 'demo-message', threadId: role === 'BRAND' ? 'arjun-user' : 'brand-user', name: role === 'BRAND' ? 'Arjun Menon' : 'Coimbatore Coffee House', preview: 'The 100 challenge idea feels exactly like our weekday crowd.', time: '10:42', image: role === 'BRAND' ? PHOTO.portrait2 : PHOTO.cafe, direction: 'received', text: 'The 100 challenge idea feels exactly like our weekday crowd.' }];
  const { data, reload } = useRemote('/api/messages', { messages: fallback }); const { push } = useToast(); const [selectedId, setSelectedId] = useState(null); const [text, setText] = useState('');
  const messages = data?.messages ?? fallback; const grouped = Object.values(messages.reduce((accumulator, message) => { const key = message.threadId || message.name; if (!accumulator[key]) accumulator[key] = { id: key, name: message.name, image: message.image, messages: [] }; accumulator[key].messages.push(message); return accumulator; }, {})); const active = grouped.find((thread) => thread.id === selectedId) || grouped[0];
  useEffect(() => { if (!selectedId && grouped[0]) setSelectedId(grouped[0].id); }, [selectedId, grouped.length]);
  const send = async (event) => { event.preventDefault(); if (!text.trim() || !active?.name) return; try { await api.sendMessage({ recipient: active.name, text: text.trim(), campaign: 'Sponsor Match campaign conversation' }); setText(''); push('Message sent to the campaign partner.'); reload(); } catch (error) { push(error.message, 'error'); } };
  return <div className="dashboard-page messages-page"><PageHeader kicker="Simple conversations" title="Keep the good work moving." description="Campaign context stays attached, with every message saved to your JSON workspace." /><div className="messages-layout"><aside className="conversation-list"><div className="conversation-search"><Search size={16} /><input placeholder="Search conversations" /></div>{grouped.map((thread) => { const last = thread.messages[thread.messages.length - 1]; return <button key={thread.id} className={`conversation ${active?.id === thread.id ? 'active' : ''}`} onClick={() => setSelectedId(thread.id)}><ImageOrInitial src={thread.image} label={thread.name} className="small-avatar" /><div><strong>{thread.name}</strong><small>{last?.preview || last?.text}</small></div><span>{last?.time || 'now'}</span></button>; })}{!grouped.length && <EmptyState icon={<MessageCircle />} title="No messages yet" text="Start a conversation from a campaign or creator profile." />}</aside><section className="chat-panel"><div className="chat-head"><ImageOrInitial src={active?.image} label={active?.name} className="small-avatar" /><div><strong>{active?.name || 'Campaign partner'}</strong><small><HeartHandshake size={12} /> Campaign conversation</small></div><button className="icon-button"><MoreHorizontal size={18} /></button></div><div className="chat-context"><span><ShieldCheck size={15} /> Messages are attached to campaign context</span><Link to={role === 'BRAND' ? '/brand/collaborations' : '/creator/collaborations'}>Open board <ArrowRight size={13} /></Link></div><div className="chat-messages">{active?.messages?.length ? active.messages.map((message, index) => <div className={`message ${message.direction === 'sent' ? 'message-me' : 'message-them'}`} key={message._id || index}><span>{message.text}</span><small>{message.time || 'now'}</small></div>) : <div className="empty-inline"><MessageCircle size={16} /><span>No messages in this thread yet. Say hello.</span></div>}</div><form className="chat-compose" onSubmit={send}><button type="button" className="icon-button"><Plus size={18} /></button><input value={text} onChange={(event) => setText(event.target.value)} placeholder="Write a message..." /><button className="send-button" aria-label="Send message" disabled={!text.trim()}><Send size={16} /></button></form></section></div></div>;
}

function VerificationRequestLive({ receipt, creator, result, onAction }) { const target = receipt?.creator || creator || {}; const claimed = receipt?.result || result || 'impact result'; return <div className="verification-request"><ImageOrInitial src={target.image} alt={target.name} label={target.name || 'Creator'} className="small-avatar" /><div><strong>{target.name || 'Creator'}</strong><small>claims <b>{claimed}</b></small></div><button className="icon-action approve" onClick={() => onAction?.('BRAND_VERIFIED')} aria-label={`Verify ${target.name || 'receipt'}`}><Check size={15} /></button><button className="icon-action reject" onClick={() => onAction?.('REJECTED')} aria-label="Reject receipt"><X size={15} /></button></div>; }

function BundleBuilder({ pitches, push }) {
  const [selected, setSelected] = useState(pitches.slice(0, 2).map((pitch) => pitch._id)); const [sending, setSending] = useState(false);
  const toggle = (id) => setSelected((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
  const createBundle = async () => { const chosen = pitches.filter((pitch) => selected.includes(pitch._id) && pitch.creator?._id); if (!chosen.length) return push('Choose at least one creator for the bundle.', 'error'); setSending(true); try { for (const pitch of chosen) await api.createCollaboration({ creatorId: pitch.creator._id, campaign: `Bundle campaign · ${pitch.announcement?.title || 'Selected pitches'}`, deliverables: 'Shared campaign bundle', budget: `₹${Math.round(10000 / chosen.length).toLocaleString()}`, paymentType: 'PAID', deadline: '2026-09-30', message: 'You are part of a split campaign bundle. The brand will confirm the shared milestones.' }); push(`Bundle request sent to ${chosen.length} creator${chosen.length === 1 ? '' : 's'}.`); } catch (error) { push(error.message, 'error'); } finally { setSending(false); } };
  return <section className="bundle-card"><div><div className="page-kicker">Split / bundle collaboration</div><h2>Build a team, not a bottleneck.</h2><p>Share a ₹10,000 campaign across {selected.length || 1} local voices and get more stories into the world.</p><div className="bundle-options">{pitches.map((pitch) => <button key={pitch._id} className={selected.includes(pitch._id) ? 'selected' : ''} onClick={() => toggle(pitch._id)}><span className="bundle-check">{selected.includes(pitch._id) && <Check size={12} />}</span>{pitch.creator?.category || 'Creator'}<small>{pitch.creator?.name}</small></button>)}</div></div><div className="bundle-math"><div className="bundle-amount">₹10,000<small>total campaign budget</small></div><div className="bundle-divider">÷</div><div className="bundle-amount">{selected.length || 1}<small>creator slots</small></div><div className="bundle-divider">=</div><div className="bundle-per">₹{Math.round(10000 / (selected.length || 1)).toLocaleString()}<small>per creator</small></div><button className="button button-dark" onClick={createBundle} disabled={sending}>{sending ? 'Sending...' : 'Create bundle'} <ArrowRight size={15} /></button></div></section>;
}

function BrandOverview() {
  const { data: creatorsData } = useRemote('/api/creators', { creators: DEMO_CREATORS });
  const { data: collabData } = useRemote('/api/collaborations', { collaborations: DEMO_COLLABS });
  const { data: verificationData, reload: reloadVerifications } = useRemote('/api/verifications/requests', { receipts: [] });
  const { data: announcementData } = useRemote('/api/announcements', { announcements: DEMO_ANNOUNCEMENTS });
  const { push } = useToast(); const creators = creatorsData?.creators ?? DEMO_CREATORS; const collaborations = collabData?.collaborations ?? DEMO_COLLABS; const announcements = announcementData?.announcements ?? DEMO_ANNOUNCEMENTS; const requests = verificationData?.receipts ?? [];
  const review = async (receipt, decision) => { try { await api.verifyReceipt(receipt._id, decision); push(decision === 'BRAND_VERIFIED' ? 'Receipt marked as brand verified.' : 'Receipt rejected.'); reloadVerifications(); } catch (error) { push(error.message, 'error'); } };
return <div className="dashboard-page"><DemoNotice /><PageHeader kicker="Your matchroom" title="Good morning, Coffee House." description="Here is what is moving in your matchroom."><Link className="button button-dark" to="/brand/announcements"><Plus size={17} /> New announcement</Link></PageHeader><div className="dashboard-hero brand-dashboard-hero"><div><div className="eyebrow"><span className="eyebrow-dot" /> Your matchroom is active</div><h2>There is a creator<br /><em>for that brief.</em></h2><p>Search by the impact you want to make, then let the ideas surprise you.</p><Link className="button button-light" to="/brand/discover">Find creators <ArrowRight size={16} /></Link></div><PhotoMatchroom variant="brand" compact /></div><div className="stat-grid"><StatCard icon={TrendingUp} label="Active campaigns" value={String(collaborations.filter((item) => item.status === 'ACTIVE').length).padStart(2, '0')} trend="Live now" tone="coral" /><StatCard icon={Lightbulb} label="Open announcements" value={String(announcements.length).padStart(2, '0')} trend="Ready for ideas" tone="blue" /><StatCard icon={Users} label="Creators discovered" value={String(creators.length).padStart(2, '0')} trend="Impact first" tone="yellow" /><StatCard icon={BadgeCheck} label="Pending verification" value={String(requests.length).padStart(2, '0')} trend="Review queue" tone="mint" /></div><div className="dashboard-grid overview-grid"><section className="panel panel-large"><PanelTitle title="Your live announcements" action={<Link to="/brand/announcements">View all <ArrowRight size={14} /></Link>} />{announcements.slice(0, 2).map((item) => <AnnouncementMini key={item._id} announcement={{ ...item, color: item.color || 'coral' }} />)}</section><section className="panel"><PanelTitle title="Verification requests" action={<Link to="/brand/collaborations">See workflow <ArrowRight size={14} /></Link>} />{requests.length ? requests.slice(0, 3).map((receipt) => <VerificationRequestLive key={receipt._id} receipt={receipt} onAction={(decision) => review(receipt, decision)} />) : <div className="empty-inline"><ShieldCheck size={17} /><span>No pending verification requests.</span></div>}</section><section className="panel panel-large"><PanelTitle title="Active collaborations" action={<Link to="/brand/collaborations">Open board <ArrowRight size={14} /></Link>} />{collaborations.length ? collaborations.map((collab) => <CollaborationRow key={collab._id} collab={collab} />) : <EmptyState icon={<HeartHandshake />} title="No collaborations yet" text="Open a creator profile to request one." />}</section><section className="panel impact-panel"><div className="impact-orbit"><Receipt size={22} /></div><div><div className="page-kicker">Your discovery signal</div><h3>{creators.reduce((sum, item) => sum + (item.verifiedReceipts || 0), 0)} <small>verified receipts</small></h3><p>proof from creators in your matchroom</p></div><div className="mini-bars"><i style={{ height: '40%' }} /><i style={{ height: '68%' }} /><i style={{ height: '53%' }} /><i style={{ height: '86%' }} /><i style={{ height: '72%' }} /></div></section></div></div>;
}

function CreatorDetail() {
  const { id } = useParams(); const navigate = useNavigate(); const { push } = useToast(); const fallback = DEMO_CREATORS.find((creator) => creator._id === id) || DEMO_CREATORS[0]; const { data } = useRemote(`/api/creators/${id}`, { creator: fallback }); const creator = data?.creator || fallback; const [showRequest, setShowRequest] = useState(false); const [saving, setSaving] = useState(false);
  const shortlist = async () => { setSaving(true); try { await api.addShortlist(creator._id); push(`${creator.name} added to your shortlist.`); } catch (error) { push(error.message, 'error'); } finally { setSaving(false); } };
  return <div className="dashboard-page"><button className="back-link page-back" onClick={() => navigate('/brand/discover')}><ArrowLeft size={15} /> Back to discovery</button><div className="profile-hero"><ImageOrInitial src={creator.image} alt={creator.name} label={creator.name} className="profile-photo" /><div className="profile-hero-copy"><div className="mini-top"><Badge tone="mint" icon={<BadgeCheck size={13} />}>Brand verified creator</Badge><span><MapPin size={13} /> {creator.location}</span></div><h1>{creator.name}</h1><p className="profile-handle">{creator.username} · {creator.category} creator</p><p>{creator.bio}</p><div className="profile-actions"><button className="button button-dark" onClick={() => setShowRequest(true)}><HeartHandshake size={16} /> Request collaboration</button><button className="button button-outline" onClick={shortlist} disabled={saving}>Shortlist <Plus size={16} /></button></div></div><div className="profile-side-stat"><span>Followers</span><strong>{creator.followers}</strong><small>secondary signal</small></div></div><div className="profile-stat-strip"><div><span className="stat-icon stat-coral"><Receipt size={17} /></span><strong>{creator.receiptCount || creator.receipts?.length || 0}</strong><small>total receipts</small></div><div className="featured-profile-stat"><span className="stat-icon stat-mint"><BadgeCheck size={17} /></span><strong>{creator.receipts?.[0]?.result || 'Verified impact'}</strong><small>strongest result</small></div><div><span className="stat-icon stat-yellow"><ThumbsUp size={17} /></span><strong>{creator.vouches || 0}</strong><small>verified vouches</small></div><div><span className="stat-icon stat-blue"><Instagram size={17} /></span><strong>{creator.platforms?.length || 1}</strong><small>active platforms</small></div></div><div className="profile-detail-grid"><section className="panel"><PanelTitle title="Impact receipts" action={<Badge tone="coral"><Receipt size={13} /> Search by impact</Badge>} /><p className="panel-intro">Evidence of real-world movement, reviewed by the businesses involved.</p><div className="receipt-list">{(creator.receipts || []).map((receipt, index) => <ReceiptCard key={receipt._id || index} receipt={receipt} />)}</div></section><section className="panel profile-vouches"><PanelTitle title="Verified vouches" action={<Badge tone="yellow"><ThumbsUp size={13} /> {creator.vouches || 0}</Badge>} /><VouchCard creator={creator} /><VouchCard creator={creator} second /></section><section className="panel portfolio-panel"><PanelTitle title="Previous work" /><div className="portfolio-grid"><img src={PHOTO.cafe} alt="Cafe campaign" /><img src={PHOTO.product} alt="Product campaign" /><img src={PHOTO.studio} alt="Creator campaign" /></div></section></div>{showRequest && <CollaborationModal creator={creator} onClose={() => setShowRequest(false)} />}</div>;
}

function CreatorPitches() {
  const fallback = DEMO_PITCHES.filter((pitch) => pitch.creator?._id === 'arjun' || pitch._id === 'pitch-basic');
  const { data, loading } = useRemote('/api/pitches/mine', { pitches: fallback });
  const { push } = useToast(); const navigate = useNavigate();
  const pitches = data?.pitches ?? fallback;
  const reuse = async (pitch) => { try { await api.reusePitch(pitch._id); push('Similar active opportunities found. Adapt your idea and resubmit.'); navigate('/creator/opportunities'); } catch (error) { push(error.message, 'error'); } };
  return <div className="dashboard-page"><PageHeader kicker="Your creative work" title="Pitches with a pulse." description="Your ideas stay yours - even when one brief says not today."><Link to="/creator/opportunities" className="button button-dark"><Plus size={17} /> Find a brief</Link></PageHeader><div className="second-chance-callout"><div className="second-chance-icon">↻</div><div><div className="page-kicker">Second-Chance Pitch</div><h3>One no does not have to be wasted work.</h3><p>Reuse, edit and resubmit the thinking when a similar brief appears.</p></div><Badge tone="yellow">Reuse the good stuff</Badge></div>{loading && <div className="inline-loading">Loading your pitches...</div>}<div className="creator-pitch-list">{pitches.map((pitch) => <article className="creator-pitch-card" key={pitch._id}><div className="creator-pitch-status"><Badge tone={pitch.status === 'REJECTED' ? 'neutral' : pitch.status === 'SHORTLISTED' ? 'mint' : 'coral'}>{pitch.status || 'SUBMITTED'}</Badge><span>{pitch.createdAt ? new Date(pitch.createdAt).toLocaleDateString() : 'Recent'}</span></div><div className="creator-pitch-content"><div className="pitch-note"><Lightbulb size={18} /><span>Pitch for <strong>{pitch.announcement?.brand || 'Sponsor Match brand'}</strong></span></div><h2>{pitch.title}</h2><p>{pitch.concept}</p><div className="pitch-meta"><span><Receipt size={14} /> {pitch.receipts || pitch.creator?.receiptCount || 0} relevant receipts</span><span><CircleDollarSign size={14} /> {pitch.budget || 'Budget discussed'}</span><span><Clock3 size={14} /> {pitch.timeline || '14 day delivery'}</span></div></div><div className="creator-pitch-side">{pitch.status === 'REJECTED' ? <><div><strong>Your pitch was not selected.</strong><small>But the idea may fit another room.</small></div><button className="button button-dark button-small" onClick={() => reuse(pitch)}>Reuse this pitch <ArrowRight size={14} /></button></> : <><div className="pitch-side-illustration"><Sparkles size={18} /></div><small>{pitch.status === 'SHORTLISTED' ? 'Brand is reviewing your fit.' : 'Awaiting brand review.'}</small></>}</div></article>)}</div>{!pitches.length && <EmptyState icon={<Lightbulb />} title="No pitches yet" text="Open a brief and send your first idea." />}</div>;
}

function ReceiptsPage() {
  const { user } = useAuth(); const { push } = useToast(); const creatorId = user?.profileId || user?._id || 'arjun';
  const { data, reload } = useRemote(`/api/creators/${creatorId}/receipts`, { receipts: DEMO_CREATORS[0].receipts });
  const [adding, setAdding] = useState(false); const receipts = data?.receipts ?? DEMO_CREATORS[0].receipts;
  const [form, setForm] = useState({ title: '', type: 'Footfall', description: '', date: '', brand: '', campaign: '', result: '', visibility: 'Public', evidenceUrl: '' });
  const set = (key, value) => setForm((current) => ({ ...current, [key]: value }));
  const submit = async (event) => { event.preventDefault(); try { await api.createReceipt(form); push('Receipt added. Request verification when you are ready.'); setAdding(false); setForm({ title: '', type: 'Footfall', description: '', date: '', brand: '', campaign: '', result: '', visibility: 'Public', evidenceUrl: '' }); reload(); } catch (error) { push(error.message, 'error'); } };
  const requestVerification = async (receipt) => { try { await api.requestVerification(receipt._id); push('Verification request sent to the related brand.'); reload(); } catch (error) { push(error.message, 'error'); } };
  return <div className="dashboard-page"><PageHeader kicker="Receipts, not reach" title="My receipts" description="Document the real-world movement your work creates."><button className="button button-dark" onClick={() => setAdding(!adding)}>{adding ? <X size={17} /> : <Plus size={17} />} {adding ? 'Close form' : 'Add receipt'}</button></PageHeader><div className="receipt-headline"><div className="receipt-headline-number"><Receipt size={23} /><strong>{receipts.length}</strong><small>receipts on profile</small></div><div><h3>Proof compounds.</h3><p>Request a review from the business involved. Verified evidence is the signal brands come looking for.</p></div><div className="receipt-chain"><span>Created</span><ArrowRight size={14} /><span>Reviewed</span><ArrowRight size={14} /><span>Verified</span></div></div>{adding && <form className="panel receipt-editor" onSubmit={submit}><div className="editor-heading"><div><div className="page-kicker">New receipt</div><h2>What moved because of your work?</h2></div><Badge tone="neutral"><Clock3 size={13} /> Creator submitted</Badge></div><div className="editor-grid"><Field label="Receipt title" value={form.title} onChange={(value) => set('title', value)} required placeholder="Restaurant campaign - 32 customer visits" /><label className="field"><span>Receipt type <i>*</i></span><div className="field-input"><select value={form.type} onChange={(event) => set('type', event.target.value)}><option>Footfall</option><option>Coupon Redemption</option><option>Customer Response</option><option>Purchase / Conversion</option><option>Business Testimonial</option><option>Campaign Result</option><option>Word of Mouth</option></select></div></label><Field label="Related brand / business" value={form.brand} onChange={(value) => set('brand', value)} required /><Field label="Campaign name" value={form.campaign} onChange={(value) => set('campaign', value)} /><Field label="Result / value" value={form.result} onChange={(value) => set('result', value)} required placeholder="32 visits" /><Field label="Date" value={form.date} onChange={(value) => set('date', value)} type="date" /><label className="field field-wide"><span>What happened? <i>*</i></span><div className="field-input"><textarea rows={4} value={form.description} onChange={(event) => set('description', event.target.value)} placeholder="Describe the connection between your content and the result." required /></div></label></div><div className="editor-footer"><span><LockKeyhole size={15} /> You control visibility.</span><button className="button button-dark">Save receipt <Check size={15} /></button></div></form>}<div className="receipt-page-list">{receipts.map((receipt, index) => <div className="receipt-page-row" key={receipt._id || index}><ReceiptCard receipt={receipt} /><div className="receipt-row-actions">{receipt.status === 'BRAND_VERIFIED' ? <Badge tone="mint" icon={<BadgeCheck size={13} />}>Visible to brands</Badge> : receipt.status === 'VERIFICATION_REQUESTED' ? <Badge tone="yellow" icon={<Clock3 size={13} />}>Verification requested</Badge> : <button className="button button-outline button-small" onClick={() => requestVerification(receipt)}>Request verification <Send size={13} /></button>}<button className="quiet-button" aria-label="More receipt actions"><MoreHorizontal size={17} /></button></div></div>)}</div></div>;
}

function MessagesPage({ role }) {
  const fallback = [{ _id: 'demo-message', name: role === 'BRAND' ? 'Arjun Menon' : 'Coimbatore Coffee House', preview: 'The 100 challenge idea feels exactly like our weekday crowd.', time: '10:42', unread: 2, image: role === 'BRAND' ? PHOTO.portrait2 : PHOTO.cafe }];
  const { data, reload } = useRemote('/api/messages', { messages: fallback }); const { push } = useToast(); const [selected, setSelected] = useState(null); const [text, setText] = useState('');
  const messages = data?.messages ?? fallback; const active = selected || messages[0];
  useEffect(() => { if (!selected && messages[0]) setSelected(messages[0]); }, [selected, messages]);
  const send = async (event) => { event.preventDefault(); if (!text.trim() || !active?.name) return; try { await api.sendMessage({ recipient: active.name, text: text.trim() }); setText(''); push('Message sent.'); reload(); } catch (error) { push(error.message, 'error'); } };
  return <div className="dashboard-page messages-page"><PageHeader kicker="Simple conversations" title="Keep the good work moving." description="Campaign context stays attached, without turning this into another social network." /><div className="messages-layout"><aside className="conversation-list"><div className="conversation-search"><Search size={16} /><input placeholder="Search conversations" /></div>{messages.map((message) => <button key={message._id} className={`conversation ${active?._id === message._id ? 'active' : ''}`} onClick={() => setSelected(message)}><ImageOrInitial src={message.image} label={message.name} className="small-avatar" /><div><strong>{message.name}</strong><small>{message.preview || message.text}</small></div><span>{message.time || 'now'}</span>{message.unread && <i>{message.unread}</i>}</button>)}</aside><section className="chat-panel"><div className="chat-head"><ImageOrInitial src={active?.image} label={active?.name} className="small-avatar" /><div><strong>{active?.name || 'Campaign partner'}</strong><small><HeartHandshake size={12} /> Campaign conversation</small></div><button className="icon-button"><MoreHorizontal size={18} /></button></div><div className="chat-context"><span><ShieldCheck size={15} /> Conversation attached to active campaign</span><Link to={role === 'BRAND' ? '/brand/collaborations' : '/creator/collaborations'}>Open board <ArrowRight size={13} /></Link></div><div className="chat-messages"><div className="date-divider">MESSAGES</div>{active?.text ? <div className="message message-them"><span>{active.text}</span><small>{active.time || 'now'}</small></div> : <><div className="message message-them"><span>Hi! We saw your latest campaign idea.</span><small>10:31</small></div><div className="message message-me"><span>Thanks! I would love to make the result measurable, not just pretty.</span><small>10:36</small></div></>}</div><form className="chat-compose" onSubmit={send}><button type="button" className="icon-button"><Plus size={18} /></button><input value={text} onChange={(event) => setText(event.target.value)} placeholder="Write a message..." /><button className="send-button" aria-label="Send message"><Send size={16} /></button></form></section></div></div>;
}

function ShortlistPage() {
  const { data, loading, reload } = useRemote('/api/shortlist', { shortlist: DEMO_CREATORS.slice(0, 3) });
  const { push } = useToast();
  const navigate = useNavigate();
  const creators = data?.shortlist ?? DEMO_CREATORS.slice(0, 3);
  const remove = async (creator) => { try { await api.removeShortlist(creator._id); push(`${creator.name} removed from shortlist.`); reload(); } catch (error) { push(error.message, 'error'); } };
  return <div className="dashboard-page"><PageHeader kicker="Your decision room" title="Shortlist the signal." description="Keep promising creators close while your brief becomes a collaboration."><Link to="/brand/discover" className="button button-dark"><Compass size={16} /> Find more creators</Link></PageHeader><div className="shortlist-summary"><div className="shortlist-summary-icon"><HeartHandshake size={21} /></div><div><strong>{creators.length} creators saved</strong><span>Compare proof, pitches and fit before you request a collaboration.</span></div><div className="shortlist-progress"><span><i style={{ width: `${Math.min(creators.length * 24, 100)}%` }} /></span><small>matchroom ready</small></div></div>{loading && <div className="inline-loading">Loading your shortlist...</div>}<div className="shortlist-grid">{creators.map((creator) => <article className="shortlist-card" key={creator._id}><div className="shortlist-card-top"><ImageOrInitial src={creator.image} alt={creator.name} label={creator.name} className="medium-avatar" /><button className="icon-button" onClick={() => remove(creator)} aria-label={`Remove ${creator.name}`}><X size={16} /></button></div><h2>{creator.name}</h2><p>{creator.category} · {creator.location}</p><div className="shortlist-stats"><span><Receipt size={14} /><strong>{creator.verifiedReceipts || 0}</strong> verified</span><span><ThumbsUp size={14} /><strong>{creator.vouches || 0}</strong> vouches</span></div><div className="shortlist-result"><Badge tone="mint" icon={<BadgeCheck size={12} />}>{creator.receipts?.[0]?.result || 'Impact profile'}</Badge></div><button className="button button-light button-full" onClick={() => navigate(`/brand/creators/${creator._id}`)}>Open profile <ArrowRight size={14} /></button></article>)}</div>{!creators.length && <EmptyState icon={<HeartHandshake />} title="Your shortlist is waiting" text="Save a creator from discovery when their proof feels like a fit." />}</div>;
}

function CreatorCard({ creator }) {
  const navigate = useNavigate();
  const { push } = useToast();
  const [saving, setSaving] = useState(false);
  const shortlist = async () => { setSaving(true); try { await api.addShortlist(creator._id); push(`${creator.name} added to shortlist.`); } catch (error) { push(error.message, 'error'); } finally { setSaving(false); } };
  return <article className="creator-card"><div className="creator-card-image"><ImageOrInitial src={creator.image} alt={creator.name} label={creator.name} /><span className="card-location"><MapPin size={12} /> {creator.location}</span><button className="card-save" onClick={shortlist} disabled={saving} aria-label="Shortlist creator"><HeartHandshake size={16} /></button></div><div className="creator-card-body"><div className="creator-card-name"><div><h3>{creator.name}</h3><span>{creator.username}</span></div><Badge tone="mint" icon={<BadgeCheck size={13} />}>Verified</Badge></div><p>{creator.category} <span>·</span> {creator.audience}</p><div className="reach-line"><span>Followers <b>{creator.followers}</b></span><span>Platforms <b>{creator.platforms?.length || 1}</b></span></div><div className="impact-block"><div className="impact-block-head"><strong>Impact</strong><span>Proof &gt; popularity</span></div><div className="impact-numbers"><div><Receipt size={15} /><strong>{creator.receiptCount || creator.receipts?.length || 0}</strong><small>receipts</small></div><div><BadgeCheck size={15} /><strong>{creator.verifiedReceipts || 0}</strong><small>brand verified</small></div><div><ThumbsUp size={15} /><strong>{creator.vouches || 0}</strong><small>vouches</small></div></div><div className="result-highlight"><span className="verified-check"><Check size={12} /></span><strong>{creator.receipts?.[0]?.result || 'Building proof now'}</strong></div></div><button className="button button-light button-full card-button" onClick={() => navigate(`/brand/creators/${creator._id}`)}>Open creator profile <ArrowRight size={15} /></button></div></article>;
}
